UPDATE `CreativeStyle`
SET
  `prompt` = 'Act as a senior jewelry retoucher doing scene-preserving product replacement. The uploaded product image or images are the only locked product identity source. Use the selected sample image as the target scene, composition, camera angle, lighting, mood, background, surface, props, water/fabric/material atmosphere, and non-product context only; it is not a product reference. Replace only the product/jewelry/accessory in the sample scene with the user uploaded product, as if the original sample product was removed and the uploaded product was realistically placed there. Keep the sample scene recognizable, including hand, wrist, fingers, skin, body, pose, water, fabric, surface, reflections, shadows, props, crop, and lens feel when they are part of the sample composition. The user uploaded product is locked: preserve its exact shape, stones, metal, engravings, proportions, silhouette, color, finish, gemstone layout, setting, and visible defects or details. Do not copy, mix in, or retain the sample product identity. Do not redesign, simplify, restyle, recolor, re-stone, unnaturally resize proportions, or invent a new product. Integrate the uploaded product with believable perspective, scale, contact shadows, occlusion, reflections, lighting, depth of field, hand/finger wrapping, water distortion, and physical placement when present.',
  `description` = 'حفظ صحنه عکس نمونه و جایگذاری طبیعی فقط محصول آپلودی به جای محصول نمونه.'
WHERE `id` = 'style_sample_reference';
